package com.hbm.client.entity.maskman;
import com.hbm.entity.mob.maskman.*;import com.mojang.blaze3d.platform.InputConstants;import net.minecraft.client.*;import net.minecraft.resources.ResourceLocation;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.settings.*;import net.neoforged.neoforge.network.PacketDistributor;import org.lwjgl.glfw.GLFW;
/** Source nativeLSHIFT key and exact three-bar source HUD artwork; holding the key does not bypass the source release/cooldown state. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class CloudDashClient {
 public static final KeyMapping DASH=new KeyMapping("hbm.key.dash",KeyConflictContext.IN_GAME,InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_LEFT_SHIFT,"key.categories.hbm");private static boolean last;private static float fadeOut;
 @SubscribeEvent public static void input(ClientTickEvent.Pre event){var mc=Minecraft.getInstance();if(mc.player==null){last=false;return;}var key=DASH.getKey();boolean pressed=mc.screen==null&&key.getValue()!=GLFW.GLFW_KEY_UNKNOWN&&(key.getType()==InputConstants.Type.MOUSE?GLFW.glfwGetMouseButton(mc.getWindow().getWindow(),key.getValue())==GLFW.GLFW_PRESS:InputConstants.isKeyDown(mc.getWindow().getWindow(),key.getValue()));if(last!=pressed){last=pressed;CloudDashRuntime.state(mc.player).pressed=pressed;PacketDistributor.sendToServer(new MaskManDashPackets.Dash(pressed));}}
 @SubscribeEvent public static void hud(RenderGuiLayerEvent.Post event){if(!event.getName().equals(net.neoforged.neoforge.client.gui.VanillaGuiLayers.HOTBAR))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.options.hideGui)return;var data=CloudDashRuntime.state(mc.player);if(data.count<=0)return;var g=event.getGuiGraphics();var tex=ResourceLocation.parse("hbm:textures/misc/overlay_misc.png");int width=30,x=16,y=g.guiHeight()-42;g.blit(tex,x-10,y,107,18,7,10);int rows=data.count/3,finalColumns=data.count%3;for(int row=0;row<rows;row++)for(int column=0;column<3;column++){if(row==rows&&column>finalColumns)break;g.blit(tex,x+32*column,y-12*row,76,48,width,10);int div=data.stamina/30,mod=data.stamina%30,id=3*row+column,status=1,size=width;if(div<id)status=3;else if(div==id){status=2;size=(int)((float)mod*(width/30F));if(id==0)status=0;}g.blit(tex,x+32*column,y-12*row,76,18+10*status,size,10);if(div==id&&mod>=27)fadeOut=1;if(fadeOut>0&&div-1==id){g.setColor(1,1,1,fadeOut);int bar=id;if(mod>=25)bar++;if(bar/3!=row)row++;bar%=3;g.blit(tex,x+32*bar,y-12*row,76,58,width,10);fadeOut-=.04F;g.setColor(1,1,1,1);}}}
 private CloudDashClient(){}
}
